static class RebirthNativeItemCodec {
 public static string Encode(ItemValue v){using(var s=new MemoryStream())using(var w=new BinaryWriter(s)){w.Write(v.UseTimes);w.Write(v.Mods);w.Write(v.Texture);w.Write(v.Stats.Length);foreach(var x in v.Stats){w.Write((int)x.type);w.Write(x.value);w.Write(x.isBoosted);}w.Write(v.Metadata.Count);foreach(var x in v.Metadata){w.Write(x.Key);w.Write((byte)(x.Value is float?1:x.Value is int?2:0));if(x.Value is float f)w.Write(f);else if(x.Value is int n)w.Write(n);else w.Write((string)x.Value);}return Convert.ToBase64String(s.ToArray());}}
 public static bool TryDecode(string text,out ItemValue v){v=null;try{using(var s=new MemoryStream(Convert.FromBase64String(text)))using(var r=new BinaryReader(s)){v=new ItemValue{UseTimes=r.ReadSingle(),Mods=r.ReadString(),Texture=r.ReadString()};v.Stats=new ItemValue.Stat[r.ReadInt32()];for(int i=0;i<v.Stats.Length;i++)v.Stats[i]=new ItemValue.Stat{type=(PassiveEffects)r.ReadInt32(),value=r.ReadInt16(),isBoosted=r.ReadBoolean()};int n=r.ReadInt32();for(int i=0;i<n;i++){string k=r.ReadString();byte kind=r.ReadByte();v.Metadata[k]=kind==1?(object)r.ReadSingle():kind==2?(object)r.ReadInt32():r.ReadString();}return s.Position==s.Length;}}catch{return false;}}
}
