 public static void ExerciseReplyOrdering(Receipt r)
 {
  Cards.Clear();Clients.Clear();InScope=PhysicalScope=true;Durable=false;
  r.Expected=Preview(r);r.Before=r.Expected;r.Admitted=true;r.OutputInvoking=true;
  var player=new EntityPlayerLocal();var world=new World{Primary=player,Registered=player};player.world=world;GameManager.Instance.World=world;
  var c=new Client{Receipt=r,Player=player};Clients[r.Operation]=c;
  string prior=Encode(r);var known=Decode(prior);known.OutputInvoking=false;known.NativeDelivered=true;c.PendingOutcome=known;c.PendingExpected=prior;
  var ack=Decode(Encode(r));ack.Before=string.Empty;ack.OutputInvoking=false;ack.NativeDelivered=false;
  WorldScopeCalls=0;ReceiveClient(new World{Primary=player},player.entityId,Encode(ack));
  if(WorldScopeCalls!=0||!ReferenceEquals(c.PendingOutcome,known))throw new Exception("stale-world reply changed live repair scope");
  ReceiveClient(world,player.entityId+1,Encode(ack));if(WorldScopeCalls!=0)throw new Exception("foreign player reply changed repair scope");
  ReceiveClient(world,player.entityId,Encode(ack));
  if(!ReferenceEquals(c.Receipt,r)||!ReferenceEquals(c.PendingOutcome,known))throw new Exception("delayed ACK replaced native outcome's uncommitted expected head");
  Durable=true;PhysicalScope=false;ReceiveClient(world,player.entityId,Encode(ack));
  if(!ReferenceEquals(c.PendingOutcome,known)||c.Receipt.NativeDelivered)throw new Exception("foreign physical scope committed original native outcome");
  PhysicalScope=true;ReceiveClient(world,player.entityId,Encode(ack));
  if(c.PendingOutcome!=null||!c.Receipt.NativeDelivered||c.Receipt.OutputInvoking||c.Receipt.Before!=known.Before)throw new Exception("metadata outcome publication/old ACK lost known native delivery");
  Clients.Clear();Cards.Clear();
 }
